function toast(title,detail=''){const t=document.getElementById('toast');t.querySelector('strong').textContent=title;t.querySelector('small').textContent=detail;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2600)}
function download(name,content,type='text/plain'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function refreshMoney(){document.querySelectorAll('[data-money]').forEach(el=>el.textContent=money(el.dataset.money));renderCapitalRows();renderCapitalNotices();renderHoldings();renderTransactions();renderFundCards();renderOverviewInvestments()}
function showPage(page){const allowed=[...document.querySelectorAll(`.nav-btn[data-page="${page}"]`)].some(b=>!b.classList.contains('hidden'))||page==='overview'||page==='profile';if(!allowed){toast('Access restricted','Your portal role does not include this workspace.');return}document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.dataset.pagePanel===page));document.querySelectorAll('.nav-btn,[data-page].mobile-bottom button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelectorAll('#mobileBottom button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('sidebar').classList.remove('open');scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav-btn,[data-go],#mobileBottom button').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page||b.dataset.go)));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.addEventListener('click',e=>{if(innerWidth<=720&&!e.target.closest('#sidebar')&&!e.target.closest('#mobileMenu'))document.getElementById('sidebar').classList.remove('open')});
function applyRole(){document.getElementById('roleLabel').textContent=roleLabels[portalRole];document.querySelectorAll('[data-entitlement]').forEach(el=>{const ent=el.dataset.entitlement;el.classList.toggle('hidden',ent!=='all'&&!ent.split(',').includes(portalRole))});const current=document.querySelector('.page.active')?.dataset.pagePanel;if(current&&!['overview','profile'].includes(current)&&!document.querySelector(`.nav-btn[data-page="${current}"]:not(.hidden)`))showPage('overview');document.getElementById('inviteUserBtn').disabled=portalRole!=='admin';document.getElementById('inviteUserLink').disabled=portalRole!=='admin'}
function openRoleMenu(){openModal('PORTAL ACCESS','Preview portal entitlement',`<div class="field"><span>Prototype role</span><select id="rolePreview"><option value="admin">Investor Admin</option><option value="investment">Investment Viewer</option><option value="finance">Finance / Treasury</option><option value="auditor">Auditor</option></select></div><p style="font-size:11px;color:#667386;line-height:1.55;margin:10px 0 0">This selector is a prototype preview. In production the signed-in user's role is assigned server-side and cannot be changed by the user.</p>`,`<button class="btn secondary" data-modal-close>Cancel</button><button class="btn primary" id="applyRoleBtn">Apply preview</button>`);document.getElementById('rolePreview').value=portalRole;document.getElementById('applyRoleBtn').addEventListener('click',()=>{portalRole=document.getElementById('rolePreview').value;applyRole();closeModal();toast('Access preview changed',roleLabels[portalRole])})}
document.getElementById('profileBtn').addEventListener('click',openRoleMenu);
function renderOverviewInvestments(){document.getElementById('overviewInvestments').innerHTML=investments.slice(0,4).map(x=>`<button class="call-item" style="border:0;background:#fff;width:100%;text-align:left" data-investment-id="${x.id}"><span class="call-icon ${x.kind.includes('Private')?'violet':''}">${x.kind.includes('Private')?'PF':'MA'}</span><span><strong>${esc(x.name)}</strong><small>${esc(x.kind)} · ${x.kind.includes('Private')?`${money(x.commitment)} commitment`:x.return.toFixed(2)+'% YTD'}</small></span><span><b>${money(x.value)}</b>${x.status}</span></button>`).join('');bindInvestmentButtons()}
function renderFundCards(){document.getElementById('fundCards').innerHTML=investments.map(x=>`<article class="fund-card" data-investment-id="${x.id}"><div class="fund-card-head"><div><h3>${esc(x.name)}</h3><p>${esc(x.kind)}</p></div><span class="tag ${x.kind.includes('Private')?'violet':'blue'}">${x.status}</span></div><div class="fund-card-value">${money(x.value)}</div><small>${x.kind.includes('Private')?`Latest NAV · ${x.irr.toFixed(1)}% net IRR`:`Published value · ${x.return.toFixed(2)}% YTD`}</small>${x.kind.includes('Private')?`<div class="fund-mini"><div><span>Commitment</span><strong>${money(x.commitment)}</strong></div><div><span>Called</span><strong>${money(x.called)}</strong></div><div><span>Unfunded</span><strong>${money(x.unfunded)}</strong></div><div><span>TVPI</span><strong>${x.tvpi.toFixed(2)}×</strong></div><div><span>DPI</span><strong>${x.dpi.toFixed(2)}×</strong></div><div><span>IRR</span><strong>${x.irr.toFixed(1)}%</strong></div></div><div class="progress"><i style="width:${(x.called/x.commitment*100).toFixed(1)}%"></i></div>`:`<div class="fund-mini"><div><span>YTD</span><strong>${x.return.toFixed(2)}%</strong></div><div><span>Benchmark</span><strong>${x.benchmark.toFixed(2)}%</strong></div><div><span>Active</span><strong>+${(x.return-x.benchmark).toFixed(2)}%</strong></div></div>`}</article>`).join('');bindInvestmentButtons()}
function bindInvestmentButtons(){document.querySelectorAll('[data-investment-id]').forEach(b=>{b.onclick=()=>openInvestment(b.dataset.investmentId)})}
function openInvestment(id){const x=investments.find(i=>i.id===id);if(!x)return;const priv=x.kind.includes('Private');openDrawer('INVESTMENT 360',x.name,`${x.kind} · ${x.status}`,`<div class="drawer-kpis"><div><span>Current value</span><strong>${money(x.value)}</strong><small>Published</small></div>${priv?`<div><span>Net IRR</span><strong>${x.irr.toFixed(1)}%</strong><small>Latest published</small></div><div><span>TVPI</span><strong>${x.tvpi.toFixed(2)}×</strong><small>DPI ${x.dpi.toFixed(2)}×</small></div>`:`<div><span>YTD</span><strong>${x.return.toFixed(2)}%</strong><small>Net TWR</small></div><div><span>Active</span><strong>+${(x.return-x.benchmark).toFixed(2)}%</strong><small>vs benchmark</small></div>`}</div><section class="drawer-section"><div class="drawer-section-head"><strong>${priv?'Commitment position':'Mandate summary'}</strong><small>${priv?'Called, unfunded and distributions':'Published investor view'}</small></div><div class="drawer-section-body"><div class="detail-list">${priv?`<div><span>Commitment</span><strong>${money(x.commitment)}</strong></div><div><span>Called</span><strong>${money(x.called)}</strong></div><div><span>Unfunded</span><strong>${money(x.unfunded)}</strong></div><div><span>Distributions</span><strong>${money(x.dist)}</strong></div>`:`<div><span>Benchmark</span><strong>Approved composite · ${x.benchmark.toFixed(2)}% YTD</strong></div><div><span>Reporting currency</span><strong>${x.ccy}</strong></div><div><span>Valuation date</span><strong>30 Aug 2026</strong></div><div><span>Publication state</span><strong>Official</strong></div>`}</div></div></section><section class="drawer-section"><div class="drawer-section-head"><strong>Available actions</strong><small>Scoped to your portal role</small></div><div class="drawer-section-body" style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn secondary" onclick="showPage('documents');closeDrawer()">Documents</button>${priv?`<button class="btn primary" onclick="showPage('capital');closeDrawer()">Capital activity</button>`:`<button class="btn primary" onclick="showPage('performance');closeDrawer()">Performance</button>`}</div></section>`)}
function renderHoldings(){const q=(document.getElementById('holdingsSearch')?.value||'').toLowerCase(),a=document.getElementById('holdingsAssetFilter')?.value||'all';document.getElementById('holdingRows').innerHTML=holdings.filter(h=>(a==='all'||h.asset===a)&&(!q||`${h.security} ${h.account} ${h.asset}`.toLowerCase().includes(q))).map(h=>`<tr><td><strong>${esc(h.security)}</strong><small>${esc(h.asset)}</small></td><td>${esc(h.account)}</td><td>${esc(h.asset)}</td><td>${h.qty}</td><td>${h.price}</td><td>${money(h.value)}</td><td>${h.weight.toFixed(2)}%</td><td class="tone-blue">+${h.ytd.toFixed(1)}%</td><td><button class="row-btn" data-holding-id="${h.id}">Open →</button></td></tr>`).join('');document.querySelectorAll('[data-holding-id]').forEach(b=>b.onclick=()=>openHolding(b.dataset.holdingId))}
function openHolding(id){const h=holdings.find(x=>x.id===id);if(!h)return;openDrawer('POSITION DETAIL',h.security,`${h.account} · ${h.asset}`,`<div class="drawer-kpis"><div><span>Market value</span><strong>${money(h.value)}</strong><small>30 Aug 2026</small></div><div><span>Weight</span><strong>${h.weight.toFixed(2)}%</strong><small>Relationship</small></div><div><span>YTD</span><strong>+${h.ytd.toFixed(1)}%</strong><small>Published</small></div></div><section class="drawer-section"><div class="drawer-section-head"><strong>Position detail</strong><small>Published client view</small></div><div class="drawer-section-body"><div class="detail-list"><div><span>Account</span><strong>${esc(h.account)}</strong></div><div><span>Asset class</span><strong>${esc(h.asset)}</strong></div><div><span>Quantity</span><strong>${h.qty}</strong></div><div><span>Reference price</span><strong>${h.price}</strong></div><div><span>Market value</span><strong>${money(h.value)}</strong></div></div></div></section>`)}
function renderTransactions(){const f=document.getElementById('transactionFilter')?.value||'all';document.getElementById('transactionRows').innerHTML=transactions.filter(t=>f==='all'||t.type===f).map(t=>`<tr><td>${t.date}</td><td><span class="tag ${t.type==='Trade'?'blue':t.type==='Income'?'violet':''}">${t.type}</span></td><td>${t.account}</td><td>${t.desc}</td><td>${t.qty}</td><td class="${t.amount<0?'tone-red':'tone-blue'}">${t.amount<0?'-':''}${money(Math.abs(t.amount))}</td><td><span class="tag blue">${t.status}</span></td><td><button class="row-btn" data-transaction-id="${t.id}">Open →</button></td></tr>`).join('');document.querySelectorAll('[data-transaction-id]').forEach(b=>b.onclick=()=>{const t=transactions.find(x=>x.id===b.dataset.transactionId);openDrawer('TRANSACTION',t.id,`${t.date} · ${t.status}`,`<section class="drawer-section"><div class="drawer-section-head"><strong>${esc(t.desc)}</strong><small>${esc(t.account)}</small></div><div class="drawer-section-body"><div class="detail-list"><div><span>Type</span><strong>${t.type}</strong></div><div><span>Quantity</span><strong>${t.qty}</strong></div><div><span>Amount</span><strong>${t.amount<0?'-':''}${money(Math.abs(t.amount))}</strong></div><div><span>State</span><strong>${t.status}</strong></div><div><span>Client visibility</span><strong>Published / settled</strong></div></div></div></section>`)});}
function renderCapitalRows(){const tf=document.getElementById('capitalTypeFilter')?.value||'all',sf=document.getElementById('capitalStatusFilter')?.value||'all';document.getElementById('capitalRows').innerHTML=capitalActivity.filter(c=>(tf==='all'||c.type===tf)&&(sf==='all'||c.status===sf)).map(c=>`<tr><td>${c.date}</td><td><strong>${c.id}</strong><small>${c.due}</small></td><td>${c.investment}</td><td>${c.type}</td><td>${money(c.amount)}</td><td><span class="tag ${c.status==='Due'?'amber':c.status==='Paid'||c.status==='Funded'?'blue':'violet'}">${c.status}</span></td><td>${c.evidence}</td><td><button class="row-btn" data-capital-id="${c.id}">Open →</button></td></tr>`).join('');bindCapitalButtons()}
function renderCapitalNotices(){const featured=capitalActivity.slice(0,2);document.getElementById('capitalNotices').innerHTML=featured.map(c=>`<article class="notice"><div><span class="tag ${c.type==='Capital call'?'amber':'violet'}">${c.type}</span><h3 style="margin-top:8px">${esc(c.investment)}</h3><p>${esc(c.purpose)}. Reference ${c.id}.</p></div><div class="amount"><strong>${money(c.amount)}</strong><small>${c.type==='Capital call'?'Due':'Expected'} ${c.due}</small></div><div class="notice-foot"><span>${c.evidence}</span><div><button class="btn secondary small" data-capital-id="${c.id}">View notice</button>${c.status==='Due'?`<button class="btn primary small" data-capital-fund="${c.id}">Fund / upload proof</button>`:''}</div></div></article>`).join('');bindCapitalButtons()}
function bindCapitalButtons(){document.querySelectorAll('[data-capital-id]').forEach(b=>b.onclick=()=>openCapital(b.dataset.capitalId));document.querySelectorAll('[data-capital-fund]').forEach(b=>b.onclick=()=>openFunding(b.dataset.capitalFund))}
function openCapital(id){const c=capitalActivity.find(x=>x.id===id);if(!c)return;openDrawer('CAPITAL ACTIVITY',c.id,`${c.type} · ${c.investment}`,`<div class="drawer-kpis"><div><span>Amount</span><strong>${money(c.amount)}</strong><small>${c.type}</small></div><div><span>Status</span><strong>${c.status}</strong><small>${c.evidence}</small></div><div><span>${c.type==='Distribution'?'Expected':'Due'}</span><strong>${c.due}</strong><small>Value date</small></div></div><section class="drawer-section"><div class="drawer-section-head"><strong>Notice details</strong><small>Reference and capital breakdown</small></div><div class="drawer-section-body"><div class="detail-list"><div><span>Investment</span><strong>${esc(c.investment)}</strong></div><div><span>Purpose</span><strong>${esc(c.purpose)}</strong></div><div><span>Payment / receipt</span><strong>${esc(c.bank)}</strong></div>${c.breakdown.map(x=>`<div><span>${esc(x[0])}</span><strong>${money(x[1])}</strong></div>`).join('')}</div></div></section><section class="drawer-section"><div class="drawer-section-head"><strong>Investor actions</strong><small>Actions are tied to this reference</small></div><div class="drawer-section-body" style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn secondary" onclick="download('${c.id}-notice.txt','${c.id}\\n${esc(c.investment)}\\n${c.type}\\n${c.amount}')">Download notice</button>${c.status==='Due'?`<button class="btn primary" onclick="closeDrawer();openFunding('${c.id}')">Fund / upload proof</button>`:''}</div></section>`)}
function openFunding(id){const c=capitalActivity.find(x=>x.id===id);if(!c)return;openModal('FUNDING WORKFLOW',`Fund ${c.id}`,`<div class="stat-row"><div><span>Amount due</span><strong>${money(c.amount)}</strong><small>${c.investment}</small></div><div><span>Due date</span><strong>${c.due}</strong><small>${c.status}</small></div><div><span>Destination</span><strong>Verified</strong><small>•••• 1448</small></div><div><span>Reference</span><strong>${c.id}</strong><small>Use on payment</small></div></div><div class="control-list" style="margin-top:12px"><div class="control-item"><span class="control-state">1</span><span><strong>Confirm verified bank instruction</strong><small>${c.bank}</small></span><em>Current</em></div><div class="control-item"><span class="control-state">2</span><span><strong>Make payment outside the portal</strong><small>The prototype does not move money directly.</small></span><em>External bank</em></div></div><div class="field" style="margin-top:12px"><span>Upload proof of payment</span><input type="file" id="paymentProof"></div><label style="display:flex;gap:8px;margin-top:11px;font-size:11px;line-height:1.45"><input type="checkbox" id="paymentConfirm" style="width:auto">I confirm I used the verified instructions shown against this notice and the payment reference is ${c.id}.</label>`,`<button class="btn secondary" data-modal-close>Cancel</button><button class="btn primary" id="submitFunding">Submit funding evidence</button>`);document.getElementById('submitFunding').addEventListener('click',()=>{const f=document.getElementById('paymentProof').files?.[0];if(!document.getElementById('paymentConfirm').checked)return toast('Confirmation required','Confirm the payment instructions used.');if(!f)return toast('Proof required','Attach proof of payment before submitting.');c.evidence=f.name;c.status='Processing';renderCapitalRows();renderCapitalNotices();closeModal();toast('Funding evidence submitted',`${c.id} is waiting for independent cash matching.`)})}
function renderDocs(){const q=(document.getElementById('documentSearch')?.value||'').toLowerCase(),year=document.getElementById('documentYear')?.value||'all';const filtered=documents.filter(d=>(year==='all'||d.year===year)&&(!q||`${d.title} ${d.investment} ${d.label}`.toLowerCase().includes(q))&&(activeDocFilter==='all'||(activeDocFilter==='signature'&&d.signature)||(activeDocFilter==='unread'&&d.unread)||d.type===activeDocFilter));document.getElementById('documentRows').innerHTML=filtered.map(d=>`<div class="doc-row"><input class="doc-check" type="checkbox" data-doc-select="${d.id}"><span class="doc-type">${d.label.slice(0,2).toUpperCase()}</span><span><strong>${esc(d.title)} ${d.unread?'<span class="tag blue" style="margin-left:5px">New</span>':''}${d.signature?'<span class="tag amber" style="margin-left:5px">Signature</span>':''}</strong><small>${esc(d.investment)} · ${d.date} · ${d.size}</small></span><span>${d.label}</span><span class="doc-actions"><button class="row-btn" data-doc-id="${d.id}">Open</button><button class="row-btn" data-doc-download="${d.id}">Download</button></span></div>`).join('')||'<div class="empty">No documents match these filters.</div>';document.querySelectorAll('[data-doc-id]').forEach(b=>b.onclick=()=>openDoc(b.dataset.docId));document.querySelectorAll('[data-doc-download]').forEach(b=>b.onclick=()=>downloadDoc(b.dataset.docDownload));document.querySelectorAll('[data-doc-select]').forEach(c=>c.onchange=updateBulkButton)}
function updateBulkButton(){const n=document.querySelectorAll('[data-doc-select]:checked').length;const b=document.getElementById('bulkDownloadBtn');b.disabled=!n;b.textContent=n?`Download selected (${n})`:'Download selected'}
function openDoc(id){const d=documents.find(x=>x.id===id);if(!d)return;d.unread=false;renderDocs();openDrawer('PUBLISHED DOCUMENT',d.title,`${d.label} · ${d.date}`,`<section class="drawer-section"><div class="drawer-section-head"><strong>Document preview</strong><small>Controlled published copy · ${d.size}</small></div><div class="drawer-section-body" style="min-height:300px;background:#fafbfd"><div style="background:#fff;border:1px solid #e2e7ef;border-radius:9px;padding:20px;max-width:420px;margin:auto;box-shadow:0 8px 24px rgba(18,34,67,.06)"><div style="font-size:18px;font-weight:850;letter-spacing:-.04em">matanho</div><div style="font-size:11px;color:#5364a9;font-weight:800;letter-spacing:.09em;margin-top:16px">${esc(d.label).toUpperCase()}</div><h3 style="font-size:15px;margin:6px 0 8px">${esc(d.title)}</h3><p style="font-size:11px;line-height:1.6;color:#4d596b">Published for ${esc(clientName)}. This preview represents the controlled client-facing version. Production downloads use entitlement-checked signed links and immutable document versions.</p><div class="detail-list"><div><span>Investment</span><strong>${esc(d.investment)}</strong></div><div><span>Publication date</span><strong>${d.date}</strong></div><div><span>Version</span><strong>Approved</strong></div></div></div></div></section><div style="display:flex;gap:7px;justify-content:flex-end"><button class="btn secondary" onclick="downloadDoc('${d.id}')">Download</button>${d.signature?`<button class="btn primary" onclick="closeDrawer();openSignature('${d.id}')">Review & sign</button>`:''}</div>`)}
function downloadDoc(id){const d=documents.find(x=>x.id===id);if(!d)return;download(`${d.title.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.txt`,`MATANHO INVESTOR PORTAL\n${clientName}\n${d.title}\n${d.investment}\nPublished ${d.date}\nControlled demo document.`);toast('Download prepared',d.title)}
function openSignature(id){const d=documents.find(x=>x.id===id);if(!d)return;openModal('E-SIGNATURE',d.title,`<p style="font-size:11px;line-height:1.55;color:#566376;margin:0 0 12px">Review the published agreement before signing. A production signature records identity, MFA/session evidence, timestamp, document hash and signatory authority.</p><div class="field"><span>Signatory name</span><input id="signName" value="Tariro M."></div><div class="field" style="margin-top:9px"><span>Authority</span><select id="signAuthority"><option>Authorised signatory</option><option>Trustee</option><option>Director</option></select></div><label style="display:flex;gap:8px;margin-top:11px;font-size:11px"><input type="checkbox" id="signConsent" style="width:auto">I confirm I have reviewed this version and am authorised to sign for ${esc(clientName)}.</label>`,`<button class="btn secondary" data-modal-close>Cancel</button><button class="btn primary" id="signSubmit">Apply signature</button>`);document.getElementById('signSubmit').onclick=()=>{if(!document.getElementById('signConsent').checked)return toast('Confirmation required','Confirm signatory authority.');d.signature=false;renderDocs();closeModal();toast('Document signed',`${d.title} has been marked signed in this prototype.`)}}
function renderRequests(){const f=document.getElementById('requestStatusFilter')?.value||'all';document.getElementById('requestRows').innerHTML=requests.filter(r=>f==='all'||r.status===f).map(r=>`<button class="request-item" style="border-left:0;border-right:0;border-top:0;background:#fff;width:100%;text-align:left" data-request-id="${r.id}"><span><strong>${r.id} · ${esc(r.title)}</strong><small>${esc(r.type)} · ${esc(r.owner)}</small><span class="request-progress"><i style="width:${r.progress}%"></i></span></span><span class="tag ${r.status==='Closed'?'blue':r.status==='Waiting on you'?'amber':'violet'}">${r.status}</span><time>${r.opened}</time></button>`).join('');document.querySelectorAll('[data-request-id]').forEach(b=>b.onclick=()=>openRequest(b.dataset.requestId))}
function openRequest(id){const r=requests.find(x=>x.id===id);if(!r)return;openDrawer('SERVICE REQUEST',`${r.id} · ${r.title}`,`${r.status} · ${r.owner}`,`<div class="drawer-kpis"><div><span>Status</span><strong>${r.status}</strong><small>${r.progress}% complete</small></div><div><span>Owner</span><strong>${r.owner}</strong><small>Client Services</small></div><div><span>Opened</span><strong>${r.opened}</strong><small>Within SLA</small></div></div><section class="drawer-section"><div class="drawer-section-head"><strong>Your request</strong><small>${r.type}</small></div><div class="drawer-section-body"><p style="font-size:11px;line-height:1.55;margin:0;color:#334154">${esc(r.detail)}</p></div></section><section class="drawer-section"><div class="drawer-section-head"><strong>Case timeline</strong><small>Recorded service history</small></div><div class="drawer-section-body">${r.timeline.map(x=>`<div class="activity-item"><time>${x[0]}</time><span><strong>${x[1]}</strong><small>${x[2]}</small></span></div>`).join('')}</div></section>${r.status!=='Closed'?`<button class="btn primary" onclick="closeDrawer();showPage('messages')">Message Client Services</button>`:''}`)}
function openRequestForm(type='Statement / report'){openModal('SERVICE REQUEST','New investor request',`<div class="form-grid"><label class="field"><span>Request type</span><select id="reqType"><option>Statement / report</option><option>Contribution / funding instruction</option><option>Withdrawal enquiry</option><option>Profile update</option><option>Mandate / investment query</option><option>Complaint / service issue</option><option>Other</option></select></label><label class="field"><span>Priority</span><select id="reqPriority"><option>Normal</option><option>Time sensitive</option></select></label><label class="field wide"><span>Message</span><textarea id="reqText" placeholder="Tell Client Services what you need, including dates or references."></textarea></label><label class="field wide"><span>Supporting evidence (optional)</span><input type="file" id="reqFile"></label></div>`,`<button class="btn secondary" data-modal-close>Cancel</button><button class="btn primary" id="reqSubmit">Submit request</button>`);document.getElementById('reqType').value=type;document.getElementById('reqSubmit').onclick=()=>{const text=document.getElementById('reqText').value.trim();if(!text)return toast('Message required','Explain what you need before submitting.');const r={id:`REQ-${2050+requests.length}`,title:document.getElementById('reqType').value,type:document.getElementById('reqType').value,status:'Open',owner:'Unassigned',opened:'Just now',progress:10,detail:text,timeline:[['Now','Submitted','Request received through investor portal']]};requests.unshift(r);renderRequests();closeModal();toast('Request submitted',`${r.id} is now in Client Services.`)}}
function renderThreads(){const q=(document.getElementById('messageSearch')?.value||'').toLowerCase();document.getElementById('messageThreads').innerHTML=threads.filter(t=>!q||`${t.title} ${t.owner}`.toLowerCase().includes(q)).map(t=>`<button class="message-thread ${t.id===activeThread?'active':''}" data-thread-id="${t.id}"><span class="avatar">${t.owner.split(/\s+/).map(x=>x[0]).join('').slice(0,2)}</span><span><strong>${esc(t.title)}${t.unread?` · ${t.unread} new`:''}</strong><small>${esc(t.owner)} · ${esc(t.messages.at(-1)?.text||'')}</small></span><time>${t.last}</time></button>`).join('');document.querySelectorAll('[data-thread-id]').forEach(b=>b.onclick=()=>{activeThread=b.dataset.threadId;const t=threads.find(x=>x.id===activeThread);t.unread=0;renderThreads();renderChat()})}
function renderChat(){const t=threads.find(x=>x.id===activeThread)||threads[0];document.getElementById('messageTitle').textContent=t.title;document.getElementById('messageMeta').textContent=`${t.owner} · ${t.role}`;document.getElementById('messageChat').innerHTML=t.messages.map(m=>`<div class="bubble ${m.who==='me'?'me':''}">${esc(m.text)}<small>${m.time}</small></div>`).join('');document.getElementById('messageChat').scrollTop=99999}
document.getElementById('sendMessageBtn').onclick=()=>{const t=threads.find(x=>x.id===activeThread),box=document.getElementById('messageCompose'),v=box.value.trim();if(!v)return;t.messages.push({who:'me',text:v,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});box.value='';renderChat();toast('Secure message sent',`Sent in ${t.title}.`)};
function renderPortalUsers(){document.getElementById('portalUsers').innerHTML=portalUsers.map(u=>`<div class="user-row"><span class="avatar">${u.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2)}</span><span><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${esc(u.scope)}</small></span><span><strong>${esc(u.role)}</strong><small>Last: ${esc(u.last)}</small></span></div>`).join('')}
function inviteUser(){if(portalRole!=='admin')return toast('Admin access required','Only an Investor Admin can invite portal users.');openModal('PORTAL ACCESS','Invite authorised user',`<div class="form-grid"><label class="field"><span>Full name</span><input id="inviteName"></label><label class="field"><span>Email</span><input id="inviteEmail" type="email"></label><label class="field"><span>Portal role</span><select id="inviteRole"><option>Investment Viewer</option><option>Finance / Treasury</option><option>Auditor</option><option>Investor Admin</option></select></label><label class="field"><span>Account scope</span><select id="inviteScope"><option>All accounts</option><option>Managed accounts only</option><option>Private funds only</option><option>Documents only</option></select></label></div><p style="font-size:11px;color:#657184;line-height:1.5">Production invitations require verified email, MFA setup and server-side entitlement assignment. Investor Admin rights should be limited to approved client administrators.</p>`,`<button class="btn secondary" data-modal-close>Cancel</button><button class="btn primary" id="inviteSubmit">Send invitation</button>`);document.getElementById('inviteSubmit').onclick=()=>{const name=document.getElementById('inviteName').value.trim(),email=document.getElementById('inviteEmail').value.trim();if(!name||!email)return toast('Name and email required','Complete the invitation details.');portalUsers.push({name,email,role:document.getElementById('inviteRole').value,scope:document.getElementById('inviteScope').value,last:'Invitation pending'});renderPortalUsers();closeModal();toast('Invitation created',`${name} added with pending access.`)}}
document.getElementById('inviteUserBtn').onclick=inviteUser;document.getElementById('inviteUserLink').onclick=inviteUser;
function renderOverviewActivity(){const items=[['Today','Investor report published','August 2026 · consolidated','New'],['28 Aug','Capital call notice','Matanho Growth Fund I · '+money(280000),'Due'],['25 Aug','Dividend received','Innscor · '+money(48220),'Settled'],['22 Aug','Portfolio rebalance completed','4 trades settled','Done'],['14 Aug','KYC annual review completed','Next review 14 Aug 2027','Current']];document.getElementById('overviewActivity').innerHTML=items.map(x=>`<div class="activity-item"><time>${x[0]}</time><span><strong>${x[1]}</strong><small>${x[2]}</small></span><em>${x[3]}</em></div>`).join('')}
function renderPerformanceRows(){const rows=investments.filter(x=>!x.kind.includes('Private')).map(x=>`<tr><td><strong>${x.name}</strong><small>${x.kind}</small></td><td>${money(x.value)}</td><td>+${(x.return/4.4).toFixed(2)}%</td><td class="tone-blue">+${x.return.toFixed(2)}%</td><td>+${(x.return*.91).toFixed(2)}%</td><td>+${(x.return*.93).toFixed(2)}%</td><td>+${x.benchmark.toFixed(2)}%</td><td class="tone-violet">+${(x.return-x.benchmark).toFixed(2)}%</td><td><button class="row-btn" data-investment-id="${x.id}">Open →</button></td></tr>`).join('');document.getElementById('performanceRows').innerHTML=rows;bindInvestmentButtons()}
function drawPerf(svgId,range='YTD',returnId,benchId){const sets={
 '1M':[[0,0],[1,.3],[2,.2],[3,.7],[4,1.1],[5,1.8],[6,2.4],[7,2.92]],
 '3M':[[0,0],[1,.9],[2,1.6],[3,2.5],[4,3.8],[5,4.5],[6,5.9],[7,7.18]],
 'YTD':[[0,0],[1,.8],[2,1.4],[3,2.6],[4,4.1],[5,5.0],[6,6.3],[7,8.4],[8,10.2],[9,12.84]],
 '1Y':[[0,0],[1,2],[2,1.1],[3,4.2],[4,5.4],[5,7.1],[6,8.8],[7,10.4],[8,11.7],[9,14.18]],
 '3Y':[[0,0],[1,4],[2,8],[3,10],[4,15],[5,19],[6,24],[7,29],[8,34],[9,40.2]]};const data=sets[range]||sets.YTD,bench=data.map(([x,y])=>[x,y*.836]),svg=document.getElementById(svgId),W=900,H=280,L=45,R=18,T=18,B=32,min=Math.min(-1,...data.map(x=>x[1])),max=Math.max(...data.map(x=>x[1]))*1.13,x=i=>L+(W-L-R)*i/(data.length-1),y=v=>T+(H-T-B)*(1-(v-min)/(max-min));let out='<defs><linearGradient id="perfArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3158e8" stop-opacity=".15"/><stop offset="100%" stop-color="#3158e8" stop-opacity="0"/></linearGradient></defs>';for(let i=0;i<5;i++){const v=max-(max-min)*i/4,yy=y(v);out+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="axis" x="${L-8}" y="${yy+3}" text-anchor="end">${v.toFixed(0)}%</text>`}const pts=data.map((d,i)=>`${x(i)},${y(d[1])}`).join(' '),bps=bench.map((d,i)=>`${x(i)},${y(d[1])}`).join(' '),area=`M ${x(0)} ${H-B} L ${data.map((d,i)=>`${x(i)} ${y(d[1])}`).join(' L ')} L ${x(data.length-1)} ${H-B} Z`;out+=`<path class="area" d="${area}"/><polyline class="benchmark" points="${bps}"/><polyline class="series" points="${pts}"/>`;['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct'].slice(0,data.length).forEach((m,i)=>out+=`<text class="axis" x="${x(i)}" y="${H-8}" text-anchor="middle">${m}</text>`);svg.innerHTML=out;if(returnId)document.getElementById(returnId).textContent=data.at(-1)[1].toFixed(2)+'%';if(benchId)document.getElementById(benchId).textContent=bench.at(-1)[1].toFixed(2)+'%'}
document.querySelectorAll('[data-perf-range]').forEach(seg=>seg.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{seg.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===btn));drawPerf(seg.closest('[data-page-panel="overview"]')?'overviewChart':'performanceChart',btn.textContent.trim(),seg.closest('[data-page-panel="overview"]')?'overviewReturn':'performanceReturn',seg.closest('[data-page-panel="overview"]')?'overviewBench':'performanceBench')}));
function openDrawer(eyebrow,title,subtitle,body){document.getElementById('drawerEyebrow').textContent=eyebrow;document.getElementById('drawerTitle').textContent=title;document.getElementById('drawerSubtitle').textContent=subtitle||'';document.getElementById('drawerBody').innerHTML=body;document.getElementById('drawerBackdrop').classList.add('show');document.getElementById('drawer').classList.add('show')}
function closeDrawer(){document.getElementById('drawerBackdrop').classList.remove('show');document.getElementById('drawer').classList.remove('show')};window.closeDrawer=closeDrawer;document.getElementById('drawerClose').onclick=closeDrawer;document.getElementById('drawerBackdrop').onclick=closeDrawer;
function openModal(eyebrow,title,body,foot=''){document.getElementById('modalEyebrow').textContent=eyebrow;document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;document.getElementById('modalFoot').innerHTML=foot;document.getElementById('modalBackdrop').classList.add('show');document.getElementById('modal').classList.add('show');document.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=closeModal)}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('show');document.getElementById('modal').classList.remove('show')};document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalBackdrop').onclick=closeModal;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeModal();document.getElementById('sidebar').classList.remove('open')}});
function openAssistant(q=''){openDrawer('PORTFOLIO ASSISTANT','Ask Matanho','Uses only your published portal data and documents.',`<div class="assistant-card"><span>CONTROLLED INVESTOR ASSISTANT</span><h3>${q?esc(q):'Ask about your relationship'}</h3><p id="assistantAnswer">${q?assistantAnswer(q):'Choose a question below or type your own. Draft answers should link back to published portfolio data or controlled documents.'}</p></div><div class="assistant-suggestions" style="margin:11px 0"><button onclick="openAssistant('What drove my YTD return?')">What drove my YTD return?</button><button onclick="openAssistant('What capital is due next?')">What capital is due next?</button><button onclick="openAssistant('Show my largest exposures')">Show my largest exposures</button></div><div class="field"><span>Ask another question</span><textarea id="assistantInput" placeholder="e.g. What is my unfunded commitment across private funds?"></textarea></div><div class="form-actions"><button class="btn primary" id="assistantAsk">Ask</button></div><section class="drawer-section" style="margin-top:12px"><div class="drawer-section-head"><strong>Source boundary</strong><small>Published client data only</small></div><div class="drawer-section-body"><p style="font-size:11px;line-height:1.55;color:#536173;margin:0">The assistant does not expose internal draft orders, unpublished research, compliance notes or other clients. Material actions still require the relevant controlled workflow.</p></div></section>`);document.getElementById('assistantAsk')?.addEventListener('click',()=>{const v=document.getElementById('assistantInput').value.trim();if(v)openAssistant(v)})}
function assistantAnswer(q){q=q.toLowerCase();if(q.includes('capital')||q.includes('unfunded'))return `Your next obligation is ${money(280000)} for Matanho Growth Fund I, due 07 September 2026. Total private-market unfunded commitment is ${money(1850000)} across two funds.`;if(q.includes('return')||q.includes('performance')||q.includes('drove'))return 'The consolidated YTD net return is +12.84% versus +10.74% for the approved benchmark. Published attribution shows security selection as the largest positive driver (+1.31%), followed by allocation (+0.64%) and currency (+0.33%).';if(q.includes('largest')||q.includes('exposure'))return 'The largest published single-security exposures are Delta Corporation at 9.10%, Innscor Africa at 7.84% and Zimplats at 6.52% of the relationship value.';if(q.includes('document'))return 'Three documents are currently unread, including the August Investor Report, August Account Statement and capital call notice CALL-2609-01. One subscription amendment requires signature.';return 'I can answer from the published portfolio, capital-activity, holdings and document data in this portal. For instructions or changes, use a controlled service request or capital workflow.'}
window.openAssistant=openAssistant;document.getElementById('assistantBtn').onclick=()=>openAssistant();document.querySelectorAll('[data-assistant-question]').forEach(b=>b.onclick=()=>openAssistant(b.dataset.assistantQuestion));
document.getElementById('notificationBtn').onclick=()=>openDrawer('NOTIFICATIONS','Investor notifications','Unread publications and actions',`<div class="call-list"><button class="call-item" style="border:0;background:#fff;text-align:left" onclick="closeDrawer();showPage('capital')"><span class="call-icon amber">CC</span><span><strong>Capital call due 07 Sep</strong><small>${money(280000)} · Matanho Growth Fund I</small></span><span>Open →</span></button><button class="call-item" style="border:0;background:#fff;text-align:left" onclick="closeDrawer();showPage('documents')"><span class="call-icon">RP</span><span><strong>August investor report published</strong><small>Consolidated relationship</small></span><span>Open →</span></button><button class="call-item" style="border:0;background:#fff;text-align:left" onclick="closeDrawer();showPage('requests')"><span class="call-icon violet">SR</span><span><strong>Request REQ-2041 updated</strong><small>Tax statement · Client Services</small></span><span>Open →</span></button></div>`);
document.getElementById('relationshipSwitcher').onclick=()=>{openModal('RELATIONSHIP VIEW','Select investment view',`<div class="field"><span>View</span><select id="relationshipView"><option>Consolidated relationship</option>${investments.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></div><p style="font-size:11px;color:#647184;line-height:1.5">A production account switcher only lists portfolios and funds the signed-in user is entitled to see.</p>`,`<button class="btn secondary" data-modal-close>Cancel</button><button class="btn primary" id="relationshipApply">Apply</button>`);setTimeout(()=>{const apply=document.getElementById('relationshipApply');if(apply)apply.onclick=()=>{document.getElementById('topContext').textContent=document.getElementById('relationshipView').value;closeModal();toast('View changed',document.getElementById('topContext').textContent)}},0)};
document.getElementById('currencySelect').onchange=e=>{reportingCurrency=e.target.value;refreshMoney();toast('Reporting currency changed',`${reportingCurrency} equivalent view applied to portal amounts.`)};
document.getElementById('holdingsSearch').oninput=renderHoldings;document.getElementById('holdingsAssetFilter').onchange=renderHoldings;document.getElementById('transactionFilter').onchange=renderTransactions;document.getElementById('capitalTypeFilter').onchange=renderCapitalRows;document.getElementById('capitalStatusFilter').onchange=renderCapitalRows;document.getElementById('documentSearch').oninput=renderDocs;document.getElementById('documentYear').onchange=renderDocs;document.getElementById('requestStatusFilter').onchange=renderRequests;document.getElementById('messageSearch').oninput=renderThreads;
document.querySelectorAll('[data-doc-filter]').forEach(b=>b.onclick=()=>{activeDocFilter=b.dataset.docFilter;document.querySelectorAll('[data-doc-filter]').forEach(x=>x.classList.toggle('active',x===b));renderDocs()});
document.getElementById('bulkDownloadBtn').onclick=()=>{const ids=[...document.querySelectorAll('[data-doc-select]:checked')].map(x=>x.dataset.docSelect);download('matanho-investor-document-bundle.txt',ids.map(id=>documents.find(d=>d.id===id)?.title).filter(Boolean).join('\n'));toast('Document bundle prepared',`${ids.length} selected documents included.`)};
document.querySelectorAll('[data-sign-doc]').forEach(b=>b.onclick=()=>openSignature(b.dataset.signDoc));
document.querySelectorAll('[data-action="new-request"]').forEach(b=>b.onclick=()=>openRequestForm());document.querySelectorAll('[data-request-template]').forEach(b=>b.onclick=()=>openRequestForm(b.dataset.requestTemplate));
document.querySelectorAll('[data-action="new-capital-request"]').forEach(b=>b.onclick=()=>openRequestForm('Contribution / funding instruction'));
document.querySelectorAll('[data-action="bank-instructions"]').forEach(b=>b.onclick=()=>openDrawer('BANK INSTRUCTIONS','Verified distribution & funding controls','Destination details cannot be changed by editing a normal profile field.',`<section class="drawer-section"><div class="drawer-section-head"><strong>Current verified distribution account</strong><small>Client master · controlled state</small></div><div class="drawer-section-body"><div class="detail-list"><div><span>Bank</span><strong>CBZ Bank</strong></div><div><span>Currency</span><strong>USD</strong></div><div><span>Account</span><strong>•••• 0482</strong></div><div><span>Last verified</span><strong>22 Jul 2026</strong></div><div><span>Control</span><strong>Independent verification required for any change</strong></div></div></div></section><button class="btn secondary" onclick="closeDrawer();openRequestForm('Profile update')">Request bank-detail change</button>`));
document.querySelectorAll('[data-action="profile-update"]').forEach(b=>b.onclick=()=>openRequestForm('Profile update'));
document.querySelectorAll('[data-action="download-summary"]').forEach(b=>b.onclick=()=>download('matanho-investor-pack.txt',`MATANHO INVESTOR PACK\n${clientName}\nPublished 30 Aug 2026\nRelationship NAV ${money(19480000)}\nYTD return 12.84%\nUnfunded commitments ${money(1850000)}\nNext capital call ${money(280000)} due 07 Sep 2026`));
document.querySelectorAll('[data-action="download-commitment-schedule"]').forEach(b=>b.onclick=()=>download('commitment-schedule.csv','Fund,Commitment,Called,Unfunded,IRR,TVPI\n'+investments.filter(x=>x.commitment).map(x=>`${x.name},${x.commitment},${x.called},${x.unfunded},${x.irr},${x.tvpi}`).join('\n'),'text/csv'));
document.querySelectorAll('[data-action="download-performance"]').forEach(b=>b.onclick=()=>download('performance-report.csv','Account,YTD,Benchmark,Active\n'+investments.filter(x=>x.return!==null).map(x=>`${x.name},${x.return},${x.benchmark},${(x.return-x.benchmark).toFixed(2)}`).join('\n'),'text/csv'));
document.querySelectorAll('[data-action="download-holdings"]').forEach(b=>b.onclick=()=>download('holdings.csv','Security,Account,Asset,Quantity,MarketValue,Weight,YTD\n'+holdings.map(h=>`${h.security},${h.account},${h.asset},${h.qty},${h.value},${h.weight},${h.ytd}`).join('\n'),'text/csv'));
document.getElementById('newMessageBtn').onclick=()=>{const t={id:`M${threads.length+1}`,title:'New investor message',owner:'Client Services',role:'Client Services',last:'Now',unread:0,messages:[]};threads.unshift(t);activeThread=t.id;renderThreads();renderChat();document.getElementById('messageCompose').focus()};
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();if(!q)return;const doc=documents.find(d=>d.title.toLowerCase().includes(q)||d.investment.toLowerCase().includes(q));if(doc){showPage('documents');activeDocFilter='all';document.getElementById('documentSearch').value=q;renderDocs();toast('Search results','Matching documents shown.');return}const h=holdings.find(x=>x.security.toLowerCase().includes(q));if(h){showPage('holdings');document.getElementById('holdingsSearch').value=q;renderHoldings();toast('Search results',h.security);return}const c=capitalActivity.find(x=>x.id.toLowerCase().includes(q)||x.investment.toLowerCase().includes(q));if(c){showPage('capital');openCapital(c.id);return}toast('No direct result','Try an investment, document title, capital reference or security name.')});
document.querySelectorAll('.switch').forEach(s=>s.onclick=()=>{s.classList.toggle('on');toast('Notification preference updated',s.classList.contains('on')?'Enabled':'Disabled')});
function init(){renderOverviewInvestments();renderFundCards();renderHoldings();renderTransactions();renderCapitalRows();renderCapitalNotices();renderDocs();renderRequests();renderThreads();renderChat();renderPortalUsers();renderOverviewActivity();renderPerformanceRows();drawPerf('overviewChart','YTD','overviewReturn','overviewBench');drawPerf('performanceChart','YTD','performanceReturn','performanceBench');applyRole();bindCapitalButtons()}
init();
